/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.flow;

import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import io.restassured.response.Response;
import net.civeira.phylax.features.oauth.tokensecurity.domain.TokenIntrospectionResult;
import net.civeira.phylax.integrationtest.features.oauth.fixtures.OidcTestFixtures;

/**
 * Pairwise subjects (task 4.4): a pairwise client gets a {@code sub} that is not the username,
 * stable for its sector and equal in the ID token and UserInfo; another sector gets another one; a
 * public client keeps the username.
 */
@QuarkusTest
class PairwiseSubjectFlowTest extends OidcIntegrationTestBase {

  private static final String USERINFO = "/oauth/openid/" + OidcTestFixtures.TENANT + "/userinfo";

  private Response grant() {
    Response issued = client.passwordGrant(OidcTestFixtures.TENANT, OidcTestFixtures.CLIENT_ID,
        OidcTestFixtures.CLIENT_SECRET, OidcTestFixtures.USERNAME, OidcTestFixtures.PASSWORD,
        OidcTestFixtures.SCOPE);
    Assertions.assertEquals(200, issued.statusCode(), issued.getBody().asString());
    return issued;
  }

  private String idTokenSubject() {
    return String.valueOf(decodeToken(grant().jsonPath().getString("id_token")).get("sub"));
  }

  @Test
  void pairwiseSubject_isStable_andTheSameInUserInfo() {
    clientStoreGateway.setPairwise(true);
    Response issued = grant();
    String sub = String.valueOf(decodeToken(issued.jsonPath().getString("id_token")).get("sub"));

    Assertions.assertNotEquals(OidcTestFixtures.USERNAME, sub);
    Assertions.assertEquals(sub, idTokenSubject(), "Stable for the sector");

    String token = issued.jsonPath().getString("access_token");
    Map<String, Object> access = decodeToken(token);
    Assertions.assertEquals(sub, access.get("sub"), "The access token carries the sector sub");
    Assertions.assertNull(access.get("uid"), "and never the global user id");
    String jti = String.valueOf(access.get("jti"));
    tokenLookupGateway.storeByJti(jti,
        TokenIntrospectionResult.builder().active(true).clientId(OidcTestFixtures.CLIENT_ID)
            .jti(jti).sub(OidcTestFixtures.USERNAME).localSubject(OidcTestFixtures.USERNAME)
            .build());
    Response userinfo = RestAssured.given().auth().oauth2(token).get(USERINFO);
    Assertions.assertEquals(200, userinfo.statusCode());
    Assertions.assertEquals(sub, userinfo.jsonPath().getString("sub"));

    Response introspection = RestAssured.given().auth().preemptive()
        .basic(OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET).formParam("token", token)
        .post("/oauth/openid/" + OidcTestFixtures.TENANT + "/introspect");
    Assertions.assertEquals(sub, introspection.jsonPath().getString("sub"),
        "Introspection never reveals the username");
  }

  @Test
  void anotherSector_getsAnotherSubject() {
    clientStoreGateway.setPairwise(true);
    String first = idTokenSubject();
    clientStoreGateway.setAllowedRedirects(List.of("https://other-sector.example/callback"));
    Assertions.assertNotEquals(first, idTokenSubject());
  }

  @Test
  void publicClient_keepsTheUsername() {
    Assertions.assertEquals(OidcTestFixtures.USERNAME, idTokenSubject());
  }

  @Test
  void discovery_announcesPairwise_whenConfigured() {
    Assertions.assertTrue(RestAssured
        .get("/oauth/openid/" + OidcTestFixtures.TENANT + "/.well-known/openid-configuration")
        .jsonPath().getList("subject_types_supported").contains("pairwise"));
  }
}
